// Generate dist/_redirects after the Astro build.
// Legacy Jekyll hub URLs and the old /resources/* paths are 301'd to their new
// homes in /playbooks/ or /blogs/ (decided by each article's content_type).
import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const CONTENT = path.join(ROOT, "src/content/resources");
const OUT = path.join(ROOT, "dist/_redirects");

const PLAYBOOK_TYPES = new Set(["how-to", "use-case"]);
const sectionFor = (t) => (PLAYBOOK_TYPES.has(String(t ?? "").toLowerCase()) ? "playbooks" : "blogs");

const lines = [
  "# Generated by scripts/gen-redirects.mjs — do not edit by hand.",
  "",
  "# Legacy Jekyll hub URLs",
  "/use-cases/*  /playbooks/:splat  301",
  "/use-cases    /playbooks/        301",
  "/tutorials/*  /playbooks/:splat  301",
  "/tutorials    /playbooks/        301",
  "/actors/*     /scrapers/:splat   301",
  "/actors       /scrapers/         301",
  "",
  "# Old /resources/* routes",
  "/resources     /playbooks/  301",
  "/resources/    /playbooks/  301",
];

let n = 0;
for (const f of fs.readdirSync(CONTENT).filter((f) => f.endsWith(".md"))) {
  const slug = f.replace(/\.md$/, "");
  const src = fs.readFileSync(path.join(CONTENT, f), "utf8");
  const m = src.match(/^content_type:\s*"?([^"\n]*)"?/m);
  const section = sectionFor(m ? m[1].trim() : "");
  lines.push(`/resources/${slug}   /${section}/${slug}/  301`);
  lines.push(`/resources/${slug}/  /${section}/${slug}/  301`);
  n += 1;
}

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, lines.join("\n") + "\n");
console.log(`gen-redirects: ${n} articles -> dist/_redirects (${lines.length} lines)`);
